    parser.add_argument("-h", ArgType::Boolean, 0,
        "このメッセージを表示して終了します。", "--help", ArgValue{false});
    parser.add_argument("-y", ArgType::String, 1, "help1\nhelp2", {}, ArgValue{::cw::lib::String("bbb")});
    parser.add_argument("-dbg", ArgType::String, 0, "help");
    const auto parsed = parser.parse_args();
    if (!parsed) throw std::invalid_argument("argparser main: invalid arguments");
    const auto& result = *parsed;
    if (result->getbool("help")) { parser.print_help(); return; }
    std::cout << "-y  : " << result->getstr("y") << '\n';
    std::cout << "-dbg: " << result->getstr("dbg") << "\n    : [";
